------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/configuring/core/monitors/

-- Two Samsung S24F350s: run at their max refresh (72Hz) instead of the 60Hz default
local mainMonitor = "HDMI-A-1"  -- left: workspaces 1-10 + Waybar
local sideMonitor = "HDMI-A-2"  -- right: one fixed "side" workspace

hl.monitor({
    output   = mainMonitor,
    mode     = "1920x1080@71.91",
    position = "0x0",
    scale    = 1,
})

hl.monitor({
    output   = sideMonitor,
    mode     = "1920x1080@71.91",
    position = "1920x0",
    scale    = 1,
})

-- Fallback for any other monitor you plug in
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "auto",
})


--------------------------------
---- WORKSPACES PER MONITOR ----
--------------------------------

-- "Side screen" setup: all numbered workspaces live on the main monitor,
-- so SUPER+1..0 never jumps to the other screen.
for i = 1, 10 do
    hl.workspace_rule({ workspace = tostring(i), monitor = mainMonitor, default = (i == 1) })
end

-- The side monitor always shows this one workspace (Discord, music, browser...).
-- Reach it with SUPER+arrows; throw windows over with SUPER+SHIFT+arrows.
hl.workspace_rule({ workspace = "name:side", monitor = sideMonitor, default = true, persistent = true })


