---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- See https://wiki.hypr.land/configuring/core/binds/ for more

-- Apps
hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd(terminal),    { description = "Terminal" })
hl.bind(mainMod .. " + Space",  hl.dsp.exec_cmd(menu),        { description = "App launcher" })
hl.bind(mainMod .. " + R",      hl.dsp.exec_cmd(menu),        { description = "App launcher" })
hl.bind(mainMod .. " + E",      hl.dsp.exec_cmd(fileManager), { description = "File manager" })
hl.bind(mainMod .. " + N",      hl.dsp.exec_cmd("swaync-client -t -sw"), { description = "Notification center" })
hl.bind(mainMod .. " + W",      hl.dsp.exec_cmd("~/.local/bin/wallpaper-picker"), { description = "Wallpaper picker" })
hl.bind(mainMod .. " + SHIFT + B", hl.dsp.exec_cmd("systemctl --user restart waybar.service"), { description = "Restart Waybar" })

-- Windows
hl.bind(mainMod .. " + Q",         hl.dsp.window.close(),                                          { description = "Close window" })
hl.bind(mainMod .. " + F",         hl.dsp.window.fullscreen({ action = "toggle", mode = "fullscreen" }), { description = "Fullscreen" })
hl.bind(mainMod .. " + SHIFT + F", hl.dsp.window.fullscreen({ action = "toggle", mode = "maximized" }),  { description = "Maximize (keep gaps/bar)" })
hl.bind(mainMod .. " + T",         hl.dsp.window.float({ action = "toggle" }),                     { description = "Toggle floating" })
hl.bind(mainMod .. " + P",         hl.dsp.window.pseudo(),                                         { description = "Pseudo-tile" })
hl.bind(mainMod .. " + J",         hl.dsp.layout("togglesplit"),                                   { description = "Toggle split direction" }) -- dwindle only

-- Session (SHIFT added so you can't quit Hyprland by accident)
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("pidof hyprlock || hyprlock"), { description = "Lock screen" })
hl.bind(mainMod .. " + SHIFT + E", hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"), { description = "Exit Hyprland" })
hl.bind(mainMod .. " + Escape",    hl.dsp.exec_cmd("~/.local/bin/powermenu"), { description = "Power menu" })
hl.bind(mainMod .. " + G",         hl.dsp.exec_cmd("~/.local/bin/gamemode"),  { description = "Toggle game mode" })

-- Screenshots (saved to ~/Pictures/Screenshots + copied; script: ~/.local/bin/screenshot)
hl.bind("Print",                   hl.dsp.exec_cmd("~/.local/bin/screenshot area"),   { description = "Screenshot: select area" })
hl.bind("SHIFT + Print",           hl.dsp.exec_cmd("~/.local/bin/screenshot screen"), { description = "Screenshot: whole monitor" })
hl.bind("ALT + Print",             hl.dsp.exec_cmd("~/.local/bin/screenshot window"), { description = "Screenshot: focused window" })
hl.bind(mainMod .. " + Print",     hl.dsp.exec_cmd("~/.local/bin/screenshot edit"),   { description = "Screenshot: area, then annotate" })

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Move the window itself with mainMod + SHIFT + arrow keys
hl.bind(mainMod .. " + SHIFT + left",  hl.dsp.window.move({ direction = "left" }))
hl.bind(mainMod .. " + SHIFT + right", hl.dsp.window.move({ direction = "right" }))
hl.bind(mainMod .. " + SHIFT + up",    hl.dsp.window.move({ direction = "up" }))
hl.bind(mainMod .. " + SHIFT + down",  hl.dsp.window.move({ direction = "down" }))

-- Resize the active window with mainMod + CTRL + arrow keys (hold to keep resizing).
-- Right/down = bigger, left/up = smaller. Tiled windows give/take space from their neighbour.
local resizeStep = 40 -- pixels per step
hl.bind(mainMod .. " + CTRL + right", hl.dsp.window.resize({ x =  resizeStep, y = 0, relative = true }), { repeating = true, description = "Window wider" })
hl.bind(mainMod .. " + CTRL + left",  hl.dsp.window.resize({ x = -resizeStep, y = 0, relative = true }), { repeating = true, description = "Window narrower" })
hl.bind(mainMod .. " + CTRL + down",  hl.dsp.window.resize({ x = 0, y =  resizeStep, relative = true }), { repeating = true, description = "Window taller" })
hl.bind(mainMod .. " + CTRL + up",    hl.dsp.window.resize({ x = 0, y = -resizeStep, relative = true }), { repeating = true, description = "Window shorter" })

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"),                  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"),                  { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })


