-- See https://wiki.hypr.land/configuring/core/rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

-- Blur whatever is behind the (semi-transparent) Waybar, like frosted glass
hl.layer_rule({
    name  = "waybar-blur",
    match = { namespace = "^waybar$" },

    blur         = true,
    ignore_alpha = 0.1,   -- don't blur fully transparent pixels
})

-- Small tool windows open floating + centered instead of being tiled
hl.window_rule({
    name  = "float-tool-windows",
    match = { class = "^(org\\.pulseaudio\\.pavucontrol|pavucontrol|blueman-manager|\\.blueman-manager-wrapped|nm-connection-editor|org\\.kde\\.kcalc|org\\.gnome\\.Calculator|xdg-desktop-portal-gtk|com\\.gabm\\.satty)$" },

    float  = true,
    center = true,
})

-- Same, plus a sensible default size for the mixer and bluetooth manager
hl.window_rule({
    name  = "size-tool-windows",
    match = { class = "^(org\\.pulseaudio\\.pavucontrol|pavucontrol|blueman-manager|\\.blueman-manager-wrapped|nm-connection-editor)$" },

    size = "900 600",
})

-- Picture-in-picture video (Firefox/Chrome): small, pinned on every workspace, bottom-right corner
hl.window_rule({
    name  = "picture-in-picture",
    match = { title = "^(Picture-in-Picture|Picture in picture|Bild-im-Bild)$" },

    float             = true,
    pin               = true,
    keep_aspect_ratio = true,
    size              = "480 270",
    move              = "monitor_w-496 monitor_h-286",
})

-- Steam games may tear (lower input lag) — only takes effect while game mode is on (SUPER+G).
-- content = "game" tells Hyprland it's a game, so moving the mouse doesn't break FreeSync.
hl.window_rule({
    name  = "games-immediate",
    match = { class = "^(steam_app_\\d+|gamescope)$" },

    immediate = true,
    content   = "game",
})
